import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { ChatMessage } from '../types';

const ChatPanel: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: ChatMessage = {
      role: 'user',
      text: input,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Determine if we should use geolocation for grounding
      let userLocation = null;
      if (input.toLowerCase().includes('near') || input.toLowerCase().includes('around') || input.toLowerCase().includes('restaurants')) {
        try {
          const pos = await new Promise<GeolocationPosition>((res, rej) => 
            navigator.geolocation.getCurrentPosition(res, rej)
          );
          userLocation = {
            latitude: pos.coords.latitude,
            longitude: pos.coords.longitude
          };
        } catch (e) {
          console.warn('Geolocation not allowed or failed');
        }
      }

      const response = await ai.models.generateContent({
        model: "gemini-3-pro-preview",
        contents: input,
        config: {
          tools: userLocation ? [{ googleMaps: {} }, { googleSearch: {} }] : [{ googleSearch: {} }],
          ...(userLocation && {
            toolConfig: {
              retrievalConfig: { latLng: userLocation }
            }
          })
        },
      });

      const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const urls = groundingChunks.map(chunk => {
        if (chunk.web) return { uri: chunk.web.uri, title: chunk.web.title };
        if (chunk.maps) return { uri: chunk.maps.uri, title: chunk.maps.title };
        return null;
      }).filter(Boolean) as Array<{ uri: string; title: string }>;

      const modelMsg: ChatMessage = {
        role: 'model',
        text: response.text || 'No response',
        timestamp: Date.now(),
        groundingUrls: urls.length > 0 ? urls : undefined
      };

      setMessages(prev => [...prev, modelMsg]);
    } catch (error) {
      console.error(error);
      const errorMsg: ChatMessage = {
        role: 'model',
        text: 'Error generating response. Please try again.',
        timestamp: Date.now()
      };
      setMessages(prev => [...prev, errorMsg]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="h-full flex flex-col p-6">
      <div 
        ref={scrollRef}
        className="flex-1 overflow-y-auto space-y-6 pb-24 pr-2"
      >
        {messages.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center opacity-40">
            <div className="w-16 h-16 bg-gray-800 rounded-2xl flex items-center justify-center mb-4">
              <svg className="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
              </svg>
            </div>
            <p className="text-xl font-medium">Lumina Intelligence</p>
            <p className="text-sm">Start a conversation with complex reasoning and search grounding</p>
          </div>
        )}

        {messages.map((msg, i) => (
          <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] rounded-3xl px-6 py-4 shadow-sm border ${
              msg.role === 'user' 
                ? 'bg-blue-600 border-blue-500 text-white' 
                : 'bg-gray-800 border-gray-700 text-gray-100'
            }`}>
              <div className="whitespace-pre-wrap text-[15px] leading-relaxed">
                {msg.text}
              </div>

              {msg.groundingUrls && (
                <div className="mt-4 pt-4 border-t border-gray-700/50">
                  <p className="text-[10px] uppercase tracking-wider text-gray-500 font-bold mb-2">Grounding Sources</p>
                  <div className="flex flex-wrap gap-2">
                    {msg.groundingUrls.map((link, idx) => (
                      <a 
                        key={idx} 
                        href={link.uri} 
                        target="_blank" 
                        rel="noreferrer"
                        className="text-xs bg-gray-900 border border-gray-700 hover:border-blue-500/50 text-blue-400 py-1 px-3 rounded-full transition-colors truncate max-w-[200px]"
                      >
                        {link.title || link.uri}
                      </a>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
        ))}

        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-gray-800 border border-gray-700 rounded-3xl px-6 py-4 flex items-center gap-2">
              <div className="flex gap-1">
                <div className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                <div className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                <div className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
              </div>
              <span className="text-xs text-gray-400 font-medium">Gemini is thinking...</span>
            </div>
          </div>
        )}
      </div>

      <div className="fixed bottom-8 left-1/2 -translate-x-1/2 w-full max-w-3xl px-4 pointer-events-none">
        <div className="bg-gray-900/80 backdrop-blur-xl border border-gray-800 rounded-2xl p-2 shadow-2xl pointer-events-auto flex items-end gap-2">
          <textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                handleSend();
              }
            }}
            placeholder="Ask anything (e.g. 'What's the weather like in Tokyo?' or 'Show me nearby cafes')"
            className="flex-1 bg-transparent border-0 ring-0 focus:ring-0 text-white p-3 min-h-[50px] max-h-40 overflow-y-auto resize-none"
            rows={1}
          />
          <button
            onClick={handleSend}
            disabled={!input.trim() || isLoading}
            className={`p-3 rounded-xl transition-all ${
              !input.trim() || isLoading 
                ? 'bg-gray-800 text-gray-600' 
                : 'bg-blue-600 text-white hover:bg-blue-500 shadow-lg shadow-blue-500/20'
            }`}
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatPanel;

import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";
import { GeneratedImage } from '../types';

const ImagePanel: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [images, setImages] = useState<GeneratedImage[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [aspectRatio, setAspectRatio] = useState('1:1');

  const handleGenerate = async () => {
    if (!prompt.trim() || isGenerating) return;

    setIsGenerating(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
          parts: [{ text: prompt }],
        },
        config: {
          imageConfig: {
            aspectRatio: aspectRatio as any,
          }
        },
      });

      let foundImageUrl = '';
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          const base64EncodeString = part.inlineData.data;
          foundImageUrl = `data:image/png;base64,${base64EncodeString}`;
          break;
        }
      }

      if (foundImageUrl) {
        const newImg: GeneratedImage = {
          id: Date.now().toString(),
          url: foundImageUrl,
          prompt,
          timestamp: Date.now()
        };
        setImages(prev => [newImg, ...prev]);
        setPrompt('');
      }
    } catch (error) {
      console.error('Image generation failed', error);
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="h-full flex flex-col md:flex-row">
      <div className="w-full md:w-80 p-6 border-b md:border-b-0 md:border-r border-gray-800 overflow-y-auto space-y-6">
        <div>
          <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-2">Prompt</label>
          <textarea
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder="A vibrant cyberpunk cityscape at dusk..."
            className="w-full bg-gray-900 border border-gray-800 rounded-xl p-4 text-sm text-white focus:border-blue-500 focus:ring-0 min-h-[120px] resize-none"
          />
        </div>

        <div>
          <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-2">Aspect Ratio</label>
          <div className="grid grid-cols-3 gap-2">
            {['1:1', '4:3', '16:9', '3:4', '9:16'].map(ratio => (
              <button
                key={ratio}
                onClick={() => setAspectRatio(ratio)}
                className={`text-xs py-2 rounded-lg border transition-all ${
                  aspectRatio === ratio 
                    ? 'bg-blue-600/10 border-blue-500 text-blue-400' 
                    : 'bg-gray-900 border-gray-800 text-gray-400 hover:border-gray-700'
                }`}
              >
                {ratio}
              </button>
            ))}
          </div>
        </div>

        <button
          onClick={handleGenerate}
          disabled={!prompt.trim() || isGenerating}
          className={`w-full py-4 rounded-xl font-semibold flex items-center justify-center gap-2 transition-all ${
            !prompt.trim() || isGenerating
              ? 'bg-gray-800 text-gray-500'
              : 'bg-blue-600 text-white hover:bg-blue-500 shadow-xl shadow-blue-500/20'
          }`}
        >
          {isGenerating ? (
            <>
              <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
              <span>Envisioning...</span>
            </>
          ) : (
            <>
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.641.32a2 2 0 01-2.08 0l-.641-.32a6 6 0 00-3.86-.517l-2.387.477a2 2 0 00-1.022.547l-1.012 1.012a2 2 0 00-.586 1.414V21a1 1 0 001 1h16a1 1 0 001-1v-4.159a2 2 0 00-.586-1.414l-1.012-1.012z" />
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.998 3.101c.253.111.455.31.57.559l.542 1.18c.084.18.25.312.447.354l1.28.27c.504.107.708.736.41 1.134l-.94 1.25c-.145.195-.197.444-.143.684l.354 1.58c.11.492-.41.87-.853.64l-1.42-.74a1.008 1.008 0 00-.936 0l-1.42.74c-.443.23-.963-.148-.853-.64l.354-1.58c.054-.24.002-.49-.143-.684l-.94-1.25c-.298-.398-.094-1.027.41-1.134l1.28-.27c.197-.042.363-.174.447-.354l.542-1.18c.115-.25.317-.448.57-.559a.75.75 0 01.594 0z" />
              </svg>
              <span>Generate Image</span>
            </>
          )}
        </button>
      </div>

      <div className="flex-1 p-8 overflow-y-auto">
        {images.length === 0 && !isGenerating ? (
          <div className="h-full flex flex-col items-center justify-center text-gray-600 opacity-50 text-center">
            <svg className="w-20 h-20 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
            </svg>
            <p className="text-xl font-medium">Your masterpieces will appear here</p>
            <p className="max-w-xs mt-2">Enter a prompt on the left to start generating high-quality visual art.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {isGenerating && (
              <div className="aspect-square bg-gray-800 border border-gray-700 rounded-2xl flex flex-col items-center justify-center p-6 text-center">
                <div className="w-12 h-12 border-4 border-blue-500/20 border-t-blue-500 rounded-full animate-spin mb-4"></div>
                <p className="text-sm font-medium text-gray-400">Gemini is sketching your idea...</p>
              </div>
            )}
            {images.map(img => (
              <div key={img.id} className="group relative rounded-2xl overflow-hidden border border-gray-800 bg-gray-900 shadow-lg">
                <img src={img.url} alt={img.prompt} className="w-full h-auto object-cover transition-transform duration-500 group-hover:scale-105" />
                <div className="absolute inset-0 bg-gradient-to-t from-gray-950/90 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity p-4 flex flex-col justify-end">
                  <p className="text-xs text-white line-clamp-2">{img.prompt}</p>
                  <button className="mt-3 text-[10px] bg-white/10 hover:bg-white/20 backdrop-blur-md py-1.5 px-3 rounded-lg font-bold w-fit">DOWNLOAD HD</button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default ImagePanel;

import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { GeneratedVideo } from '../types';

const VideoPanel: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [videos, setVideos] = useState<GeneratedVideo[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [hasKey, setHasKey] = useState(false);
  const [progressMessage, setProgressMessage] = useState('');

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      if (window.aistudio && typeof window.aistudio.hasSelectedApiKey === 'function') {
        // @ts-ignore
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasKey(selected);
      } else {
        // Fallback for dev environments if needed
        setHasKey(true);
      }
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    // @ts-ignore
    if (window.aistudio && typeof window.aistudio.openSelectKey === 'function') {
      // @ts-ignore
      await window.aistudio.openSelectKey();
      // Assume success as per instructions to avoid race conditions
      setHasKey(true);
    }
  };

  const handleGenerate = async () => {
    if (!prompt.trim() || isGenerating) return;

    setIsGenerating(true);
    setProgressMessage('Submitting request to Veo 3.1...');

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt,
        config: {
          numberOfVideos: 1,
          resolution: '720p',
          aspectRatio: '16:9'
        }
      });

      const messages = [
        'Interpreting cinematic direction...',
        'Generating keyframes...',
        'Synthesizing temporal consistency...',
        'Rendering final motion paths...',
        'Finalizing MP4 stream...'
      ];
      let msgIdx = 0;

      while (!operation.done) {
        setProgressMessage(messages[msgIdx % messages.length]);
        msgIdx++;
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await ai.operations.getVideosOperation({ operation: operation });
      }

      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      if (downloadLink) {
        const fetchUrl = `${downloadLink}&key=${process.env.API_KEY}`;
        setVideos(prev => [{
          id: Date.now().toString(),
          url: fetchUrl,
          prompt,
          status: 'completed',
          timestamp: Date.now()
        }, ...prev]);
        setPrompt('');
      }
    } catch (error: any) {
      console.error('Video generation failed', error);
      if (error.message?.includes('Requested entity was not found')) {
        setHasKey(false);
      }
    } finally {
      setIsGenerating(false);
      setProgressMessage('');
    }
  };

  if (!hasKey) {
    return (
      <div className="h-full flex flex-col items-center justify-center p-8 text-center bg-gray-950/50">
        <div className="max-w-md bg-gray-900 border border-gray-800 rounded-3xl p-10 shadow-2xl">
          <div className="w-20 h-20 bg-blue-600/10 rounded-full flex items-center justify-center mx-auto mb-6">
            <svg className="w-10 h-10 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 7a2 2 0 012 2m4 0a6 6 0 01-7.743 5.743L11 17H9v2H7v2H4a1 1 0 01-1-1v-2.586a1 1 0 01.293-.707l5.964-5.964A6 6 0 1121 9z" />
            </svg>
          </div>
          <h2 className="text-2xl font-bold mb-3">API Key Required</h2>
          <p className="text-gray-400 mb-8 leading-relaxed">
            Veo video generation requires a paid Google Cloud project. Please select an authorized API key to access this laboratory.
          </p>
          <button
            onClick={handleSelectKey}
            className="w-full py-4 bg-blue-600 hover:bg-blue-500 text-white rounded-xl font-bold transition-all shadow-xl shadow-blue-500/20"
          >
            Select API Key
          </button>
          <p className="mt-6 text-xs text-gray-500">
            For more details, visit the <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noreferrer" className="text-blue-400 hover:underline">billing documentation</a>.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col md:flex-row">
      <div className="w-full md:w-80 p-6 border-b md:border-b-0 md:border-r border-gray-800 overflow-y-auto space-y-6">
        <div>
          <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-2 text-center md:text-left">Video Prompt</label>
          <textarea
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder="A neon hologram of a cat driving at top speed through a futuristic highway..."
            className="w-full bg-gray-900 border border-gray-800 rounded-xl p-4 text-sm text-white focus:border-blue-500 focus:ring-0 min-h-[150px] resize-none"
          />
        </div>

        <button
          onClick={handleGenerate}
          disabled={!prompt.trim() || isGenerating}
          className={`w-full py-4 rounded-xl font-semibold flex items-center justify-center gap-3 transition-all ${
            !prompt.trim() || isGenerating
              ? 'bg-gray-800 text-gray-500'
              : 'bg-indigo-600 text-white hover:bg-indigo-500 shadow-xl shadow-indigo-500/20'
          }`}
        >
          {isGenerating ? (
            <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
          ) : (
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
          )}
          <span>{isGenerating ? 'Synthesizing...' : 'Create Video'}</span>
        </button>

        {isGenerating && (
          <div className="p-4 bg-indigo-500/10 border border-indigo-500/20 rounded-xl animate-pulse">
            <p className="text-xs text-indigo-400 font-medium text-center">{progressMessage}</p>
          </div>
        )}
      </div>

      <div className="flex-1 p-8 overflow-y-auto bg-gray-950/20">
        {videos.length === 0 && !isGenerating ? (
          <div className="h-full flex flex-col items-center justify-center text-gray-600 opacity-40 text-center">
            <div className="w-24 h-24 mb-6 border-2 border-dashed border-gray-700 rounded-3xl flex items-center justify-center">
              <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24">
