import ChatPanel from './components/ChatPanel';
import ImagePanel from './components/ImagePanel';
import VideoPanel from './components/VideoPanel';
import LivePanel from './components/LivePanel';
import VisionNodePanel from './components/VisionNodePanel';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.CHAT);

  const renderContent = () => {
    switch (activeTab) {
      case AppTab.CHAT:
        return <ChatPanel />;
      case AppTab.IMAGES:
        return <ImagePanel />;
      case AppTab.VIDEOS:
        return <VideoPanel />;
      case AppTab.LIVE:
        return <LivePanel />;
      case AppTab.VISION_NODE:
        return <VisionNodePanel />;
      default:
        return <ChatPanel />;
    }
  };

  return (
    <div className="flex h-screen w-full bg-gray-950 text-gray-100">
      <Sidebar activeTab={activeTab} onTabChange={setActiveTab} />
      <div className="flex flex-col flex-1 relative overflow-hidden">
        <Header activeTab={activeTab} />
        <main className="flex-1 overflow-auto bg-gray-900/50">
          <div className="h-full w-full">
            {renderContent()}
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState } from 'react';

const VisionNodePanel: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [seal, setSeal] = useState<string>('');
  const [isCapturing, setIsCapturing] = useState(false);

  const NODE_ID = "G.V. NODE-Σ-2026";
  const ROOT_ADDRESS = "115 East Southfield Drive, Jackson, MI";
  const EIN = "41-6820289";

  // Simple SHA-256 equivalent for visual display
  const generateFiduciarySeal = async (units = 35817390.8719) => {
    const rawData = `${ROOT_ADDRESS}|${EIN}|${units}|2026`;
    const msgBuffer = new TextEncoder().encode(rawData);
    const hashBuffer = await crypto.subtle.digest('SHA-256', msgBuffer);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map(b => b.toString(16).padStart(2, '0')).join('').toUpperCase();
  };

  useEffect(() => {
    generateFiduciarySeal().then(setSeal);

    const startCamera = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ video: true });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsCapturing(true);
        }
      } catch (err) {
        console.error("Camera access failed:", err);
      }
    };

    startCamera();

    return () => {
      if (videoRef.current && videoRef.current.srcObject) {
        const stream = videoRef.current.srcObject as MediaStream;
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  useEffect(() => {
    if (!canvasRef.current || !videoRef.current) return;

    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    let animationFrame: number;
    let phase = 0;

    const draw = () => {
      const canvas = canvasRef.current!;
      const video = videoRef.current!;

      if (video.readyState === video.HAVE_ENOUGH_DATA) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;

        // Draw video frame base
        ctx.filter = 'contrast(1.2) brightness(0.8) sepia(0.2) hue-rotate(90deg)';
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        ctx.filter = 'none';

        // 3-6-9 Vortex Shimmer Overlay
        ctx.globalCompositeOperation = 'screen';
        ctx.strokeStyle = 'rgba(34, 197, 94, 0.3)';
        ctx.lineWidth = 1;

        const centerX = canvas.width / 2;
        const centerY = canvas.height / 2;
        const maxDist = Math.sqrt(centerX ** 2 + centerY ** 2);

        for (let r = 20; r < maxDist; r += 40) {
          ctx.beginPath();
          // Wave superposition logic: 3, 6, 9 frequencies
          const ripple = (Math.sin(3 * (r / 50) - phase) + 
                          Math.sin(6 * (r / 50) - (phase * 1.5)) + 
                          Math.sin(9 * (r / 50) - (phase * 2.0))) / 3;

          const dynamicRadius = r + ripple * 15;
          ctx.arc(centerX, centerY, dynamicRadius, 0, Math.PI * 2);
          ctx.stroke();
        }

        // Geometric Node Markers
        ctx.strokeStyle = 'rgba(34, 197, 94, 0.6)';
        ctx.setLineDash([5, 15]);
        ctx.beginPath();
        ctx.moveTo(centerX - 100, centerY);
        ctx.lineTo(centerX + 100, centerY);
        ctx.moveTo(centerX, centerY - 100);
        ctx.lineTo(centerX, centerY + 100);
        ctx.stroke();
        ctx.setLineDash([]);

        phase += 0.05;
      }
      animationFrame = requestAnimationFrame(draw);
    };

    draw();
    return () => cancelAnimationFrame(animationFrame);
  }, [isCapturing]);

  return (
    <div className="h-full flex flex-col p-8 overflow-y-auto">
      <div className="max-w-6xl mx-auto w-full space-y-8">

        {/* Telemetry Header */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6 pb-6 border-b border-green-500/20">
          <div>
            <div className="flex items-center gap-2 mb-2">
              <div className="w-3 h-3 bg-green-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(34,197,94,0.5)]"></div>
              <span className="text-xs font-mono font-bold text-green-500 tracking-widest">{NODE_ID}</span>
            </div>
            <h2 className="text-3xl font-black text-white tracking-tighter">SOVEREIGN VISION NODE <span className="text-green-500">Σ-01</span></h2>
            <p className="text-sm font-mono text-gray-500 mt-2">{ROOT_ADDRESS}</p>
          </div>
          <div className="bg-gray-900 border border-green-500/30 p-4 rounded-xl font-mono">
            <p className="text-[10px] text-gray-500 uppercase font-bold mb-1">Fiduciary Seal (SHA-256)</p>
            <p className="text-xs text-green-400 break-all leading-tight max-w-[300px]">{seal || 'CALCULATING...'}</p>
          </div>
        </div>

        {/* Vision Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Main Feed */}
          <div className="lg:col-span-2 relative aspect-video bg-black rounded-3xl overflow-hidden border-2 border-green-500/20 shadow-2xl shadow-green-500/5 group">
            <video ref={videoRef} autoPlay playsInline muted className="hidden" />
            <canvas ref={canvasRef} className="w-full h-full object-cover" />

            {/* UI Overlay on Video */}
            <div className="absolute top-6 left-6 flex flex-col gap-2">
              <div className="bg-black/60 backdrop-blur-md px-3 py-1 rounded border border-green-500/30 font-mono text-[10px] text-green-400">
                RESOLUTION: 2160P [UP-SCALED]
              </div>
              <div className="bg-black/60 backdrop-blur-md px-3 py-1 rounded border border-green-500/30 font-mono text-[10px] text-green-400">
                LATENCY: 14MS
              </div>
            </div>

            <div className="absolute bottom-6 right-6 font-mono text-green-500 text-[10px] text-right">
              <p>TRUST SECTOR: JACKSON_MI_01</p>
              <p>ARCHITECT: NICHOLAS YOUNG</p>
              <p>TIME: {new Date().toLocaleTimeString()}</p>
            </div>

            <div className="absolute inset-0 border-[20px] border-transparent group-hover:border-green-500/5 pointer-events-none transition-all duration-500"></div>
          </div>

          {/* Node Metadata & Controls */}
          <div className="space-y-6">
            <div className="bg-gray-900/50 border border-gray-800 rounded-2xl p-6 space-y-6">
              <div>
                <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-4">Node Telemetry</h3>
                <div className="space-y-3">
                  <div className="flex justify-between items-center text-xs">
                    <span className="text-gray-400">Fiduciary Layer</span>
                    <span className="text-green-400 font-mono">ACTIVE</span>
                  </div>
                  <div className="flex justify-between items-center text-xs">
                    <span className="text-gray-400">3-6-9 Sync</span>
                    <span className="text-green-400 font-mono">LOCKED</span>
                  </div>
                  <div className="flex justify-between items-center text-xs">
                    <span className="text-gray-400">EIN Verified</span>
                    <span className="text-green-400 font-mono">{EIN}</span>
                  </div>
                </div>
              </div>

              <div className="pt-6 border-t border-gray-800">
                <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-4">Thermal Resonance</h3>
                <div className="h-2 bg-gray-800 rounded-full overflow-hidden">
                  <div className="h-full bg-gradient-to-r from-green-600 to-green-400 w-3/4 animate-pulse"></div>
                </div>
              </div>

              <div className="pt-6 border-t border-gray-800">
                <button className="w-full bg-green-600/10 border border-green-500/30 text-green-400 py-3 rounded-xl font-bold text-sm hover:bg-green-600/20 transition-all flex items-center justify-center gap-2">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
                  </svg>
                  RE-ANCHOR TRUST SEAL
                </button>
              </div>
            </div>

            <div className="bg-blue-600/5 border border-blue-500/20 rounded-2xl p-6">
              <p className="text-[10px] font-bold text-blue-400 uppercase tracking-widest mb-2">Architect's Note</p>
              <p className="text-xs text-gray-400 leading-relaxed italic">
                "Peak CPU efficiency attained via pre-calculated parabolic resonance grids. Fiduciary anchors are immutably tied to the Jackson root node."
              </p>
            </div>
          </div>

        </div>

        {/* Audit Log */}
        <div className="bg-gray-950 border border-gray-800 rounded-2xl p-6 font-mono text-[10px] text-gray-500">
          <p className="mb-2 text-gray-400 uppercase font-bold tracking-widest">System Audit Log</p>
          <div className="space-y-1">
            <p>[{new Date().toISOString()}] NODE_BOOT: Initializing ARK-SIGMA Kernel...</p>
            <p>[{new Date().toISOString()}] VISION_STREAM: Synchronizing with Jackson Southfield Root...</p>
            <p>[{new Date().toISOString()}] SEAL_GEN: SHA-256 Anchorage established.</p>
            <p>[{new Date().toISOString()}] VORTEX_SYNC: 3-6-9 Frequency Superposition stabilized.</p>
          </div>
        </div>
      </div>
    </div>
  );
};

